// ─────────────────────────────────────────
function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

function calculerMarge(achat, vente) {
  const marge = vente - achat;
  const taux = achat > 0 ? ((marge / achat) * 100).toFixed(1) : 0;
  return { marge: parseFloat(marge.toFixed(0)), taux: parseFloat(taux) };
}

function getAlertes() { return db.produits.filter(p => p.stock <= 5 && p.stock > 0); }
function getRuptures() { return db.produits.filter(p => p.stock === 0); }

function getStats() {
  const ca = db.ventes.reduce((s, v) => s + v.montant_total, 0);
  const cout_achats = db.ventes.reduce((s, v) => s + v.prix_achat_unitaire * v.quantite, 0);
  const total_charges = db.charges.reduce((s, c) => s + c.montant, 0);
  return {
    ca: parseFloat(ca.toFixed(0)),
    cout_achats: parseFloat(cout_achats.toFixed(0)),
    benefice_brut: parseFloat((ca - cout_achats).toFixed(0)),
    benefice_net: parseFloat((ca - cout_achats - total_charges).toFixed(0)),
    total_charges: parseFloat(total_charges.toFixed(0)),
    nb_produits: db.produits.length,
    nb_clients: db.clients.length,
    nb_ventes: db.ventes.length,
    alertes_stock: getAlertes().length,
    ruptures: getRuptures().length,
  };
}

async function envoyerVersSheets(action, data) {
  if (!GAS_URL) return;
  try { await axios.post(GAS_URL, { action, ...data }); }
  catch (err) { console.error("Erreur Sheets :", err.message); }
}

// ─────────────────────────────────────────
// CHARGER LES DONNÉES DEPUIS GOOGLE SHEETS AU DÉMARRAGE
// ─────────────────────────────────────────
let _dernierChargement = 0;
const CACHE_SHEETS_MS = 60000; // 60 secondes minimum entre deux rechargements

async function chargerDepuisSheets(force = false) {
  if (!GAS_URL) { console.log("⚠️ GAS_URL non configuré — démarrage à vide"); return; }
  const maintenant = Date.now();
  if (!force && maintenant - _dernierChargement < CACHE_SHEETS_MS) return; // Cache actif
  _dernierChargement = maintenant;
  try {
    console.log("📊 Chargement des données depuis Google Sheets...");
    const resp = await axios.get(GAS_URL + "?action=charger_tout");
    const data = resp.data;

    if (!data || typeof data !== 'object') {
      console.log("⚠️ Sheets vide ou erreur — démarrage à vide");
      return;
    }
    
    // Log pour debug
    console.log(`📊 Sheets reçu: ${Object.keys(data).map(k => k + '=' + (data[k]?.length||0)).join(', ')}`);

    // ⚠️ RÉINITIALISER db avant chaque rechargement
    // → garantit que les suppressions dans Sheets sont prises en compte
    // Sauvegarder les rappels déjà envoyés pour ne pas les renvoyer
    const rappelsDejaEnvoyes = {};
    db.agenda.forEach(e => { if (e.id) rappelsDejaEnvoyes[e.id] = e.rappels_envoyes || []; });
    db.relances.forEach(r => { if (r.id) rappelsDejaEnvoyes['r_'+r.id] = r.rappels_envoyes || []; });
    db.livraisons.forEach(l => { if (l.id) rappelsDejaEnvoyes['l_'+l.id] = l.rappels_envoyes || []; });

    db.produits = [];
    db.clients = [];
    db.ventes = [];
    db.charges = [];
    db.agenda = [];
    db.relances = [];
    db.livraisons = [];

    // Charger produits
    if (data.produits && data.produits.length > 0) {
      db.produits = data.produits.map(p => ({
        id: p["ID"] || p.id || genId(),
        nom: p["Nom"] || p.nom || "",
        couleur: p["Couleur"] || p.couleur || "",
        categorie: p["Catégorie"] || p.categorie || "",
        caracteristiques: p["Caractéristiques"] || p.caracteristiques || "",
        prix_achat: parseFloat(p["Prix Achat"] || p.prix_achat) || 0,
        prix_vente: parseFloat(p["Prix Vente"] || p.prix_vente) || 0,
        prix_revendeur: parseFloat(p["Prix Revendeur"] || p.prix_revendeur) || null,
        stock_initial: parseInt(p["Stock Initial"] || p.stock_initial) || 0,
        stock: parseInt(p["Stock Actuel"] || p["Stock"] || p.stock) || 0,
        photo_url: p["Photo URL"] || p.photo_url || null,
        couleurs: p["Couleurs"] ? p["Couleurs"].split("|").map(c => { const [nom, stock] = c.split(":"); return { nom, stock: parseInt(stock) || 0 }; }) : null,
        cree_le: p["Date"] || p.cree_le || new Date().toISOString(),
      }));
      console.log(`✅ ${db.produits.length} produit(s) chargé(s)`);
    }

    // Charger clients
    if (data.clients && data.clients.length > 0) {
      db.clients = data.clients.map(c => ({
        id: c["ID"] || c.id || genId(),
        nom: c["Nom"] || c.nom || "",
        email: c["Email"] || c.email || "",
        telephone: String(c["Téléphone"] || c.telephone || ""),
        note: c["Note"] || c.note || "",
        nb_achats: parseInt(c["Nb Achats"] || c.nb_achats) || 0,
        ca_total: parseFloat(c["CA Total"] || c.ca_total) || 0,
        carte_envoyee: (c["Carte Envoyée"] || c.carte_envoyee) === true || (c["Carte Envoyée"] || c.carte_envoyee) === "TRUE" || false,
        cree_le: c["Date"] || c.cree_le || new Date().toISOString(),
        derniere_relance: c["Dernière Relance"] || c.derniere_relance || null,
        derniere_visite: (() => {
          // Sera calculée après chargement des ventes
          return c["Date"] || c.cree_le || new Date().toISOString();
        })(),
      }));
      console.log(`✅ ${db.clients.length} client(s) chargé(s)`);
    }

    // Charger ventes - TOUTES sans limite
    if (data.ventes && data.ventes.length > 0) {
      db.ventes = data.ventes.map(v => ({
        id: v["ID"] || v.id || genId(),
        client_nom: v["Client"] || v.client_nom || "",
        produit_nom: v["Produit"] || v.produit_nom || "",
        quantite: parseInt(v["Quantité"] || v.quantite) || 1,
        prix_vente: parseFloat(v["Prix Vente Unit."] || v.prix_vente) || 0,
        montant_total: parseFloat(v["Montant Total"] || v.montant_total) || 0,
        marge_totale: parseFloat(v["Marge Totale"] || v.marge_totale) || 0,
        reduction: parseFloat(v["Réduction"] || v.reduction) || 0,
        prix_achat_unitaire: parseFloat(v["Prix Achat Unit."] || v.prix_achat_unitaire) || 0,
        produit_couleur: v["Couleur"] || v.produit_couleur || "",
        date: (() => {
          const d = v["Date"] || v.date || "";
          if (!d) return new Date().toISOString();
          // Convertir "28/05/2026 15:15:04" → ISO
          if (typeof d === 'string' && d.includes('/')) {
            const [datePart, timePart] = d.split(' ');
            const [jour, mois, annee] = datePart.split('/');
            return new Date(`${annee}-${mois}-${jour}T${timePart || '00:00:00'}`).toISOString();
          }
          return new Date(d).toISOString();
        })(),
      }));
      console.log(`✅ ${db.ventes.length} vente(s) chargée(s)`);
      // Calculer derniere_visite pour chaque client depuis les ventes
      db.clients.forEach(client => {
        const ventesClient = db.ventes.filter(v => v.client_nom === client.nom);
        if (ventesClient.length > 0) {
          const dates = ventesClient.map(v => new Date(v.date)).filter(d => !isNaN(d));
          if (dates.length > 0) {
            client.derniere_visite = new Date(Math.max(...dates)).toISOString();
          }
        }
      });
    }

    // Charger charges - TOUTES sans limite
    if (data.charges && data.charges.length > 0) {
      db.charges = data.charges.map(c => ({
        id: c["ID"] || c.id || genId(),
        label: c["Libellé"] || c.label || "",
        montant: parseFloat(c["Montant"] || c.montant) || 0,
        categorie: c["Catégorie"] || c.categorie || "",
        produit_lie: c["Produit Lié"] || c.produit_lie || null,
        date: (() => {
          const d = c["Date"] || c.date || "";
          if (!d) return new Date().toISOString();
          if (typeof d === 'string' && d.includes('/')) {
            const [datePart, timePart] = d.split(' ');
            const [jour, mois, annee] = datePart.split('/');
            return new Date(`${annee}-${mois}-${jour}T${timePart || '00:00:00'}`).toISOString();
          }
          return new Date(d).toISOString();
        })(),
      }));
      console.log(`✅ ${db.charges.length} charge(s) chargée(s)`);
    }

    // Charger agenda
    if (data.agenda && data.agenda.length > 0) {
      db.agenda = data.agenda.map(e => {
        const id = e["ID"] || e.id || genId();
        return {
          id,
          titre: e["Titre"] || e.titre || "",
          date: e["Date ISO"] || e.date_iso || e.date || new Date().toISOString(),
          chatId: e["Chat ID"] || e.chatId || USERS_AUTORISES[0] || null,
          rappels_envoyes: rappelsDejaEnvoyes[id] || [],  // Restaurer rappels envoyés
          googleEventId: null,
        };
      });
      console.log(`✅ ${db.agenda.length} événement(s) chargé(s)`);
    }

    if (data.relances && data.relances.length > 0) {
      db.relances = data.relances.map(r => {
        const id = r["ID"] || r.id || genId();
        return {
          id,
          client_nom: r["Client"] || r.client_nom || "",
          client_tel: r["Téléphone"] || r.client_tel || "",
          note: r["Note"] || r.note || "",
          date: r["Date Relance"] || r.date || new Date().toISOString(),
          chatId: r["Chat ID"] || r.chatId || USERS_AUTORISES[0] || null,
          rappels_envoyes: rappelsDejaEnvoyes['r_'+id] || [],
        };
      });
      console.log(`✅ ${db.relances.length} relance(s) chargée(s)`);
    }

    if (data.livraisons && data.livraisons.length > 0) {
      db.livraisons = data.livraisons.map(l => {
        const id = l["ID"] || l.id || genId();
        return {
          id,
          client_nom: l["Client"] || l.client_nom || "",
          client_tel: l["Téléphone"] || l.client_tel || "",
          produit: l["Produit"] || l.produit || "",
          note: l["Note"] || l.note || "",
          date: l["Date Livraison"] || l.date || new Date().toISOString(),
          chatId: l["Chat ID"] || l.chatId || USERS_AUTORISES[0] || null,
          rappels_envoyes: rappelsDejaEnvoyes['l_'+id] || [],
        };
      });
      console.log(`✅ ${db.livraisons.length} livraison(s) chargée(s)`);
    }
    console.log("✅ Données rechargées depuis Google Sheets !");
  } catch (err) {
    console.error("❌ Erreur chargement Sheets :", err.message);
    console.log("⚠️ Démarrage à vide");
  }
}

// ─────────────────────────────────────────
// FIDÉLITÉ — Paliers progressifs
// ─────────────────────────────────────────
// 1er achat → plein
// 2ème achat → -8%
// 3ème achat → -10%
// 4ème+ achat → -15%

function getTauxReduction(nb_achats) {
  if (nb_achats === 1) return 0.08; // 2ème achat : -8%
  if (nb_achats === 2) return 0.10; // 3ème achat : -10%
  if (nb_achats >= 3) return 0.15;  // 4ème achat et + : -15%
  return 0; // 1er achat = plein tarif
}

function getLabelReduction(nb_achats) {
  if (nb_achats === 1) return "-8%";
  if (nb_achats === 2) return "-10%";
  if (nb_achats >= 3) return "-15%";
  return null;
}

function clientEligibleReduction(client) {
  return client.nb_achats >= 1; // Éligible dès le 2ème achat
}

function appliquerReduction(prix, nb_achats) {
  const taux = getTauxReduction(nb_achats);
  return parseFloat((prix * (1 - taux)).toFixed(0));
}

// Compat ancienne signature
const ACHAT_REDUCTION = 1;
const SUPPLEMENT_PHOTOCHROMIQUE = 7000; // Supplément photochromique en FCFA
const TAUX_REDUCTION = 0.10;

// Trouver ou créer un client (avec fidélité)
function trouverOuCreerClient(info) {
  if (!info) return null;
  const recherche = info.toLowerCase().trim();
  // Ne pas créer un client si son nom correspond à un produit
  const estUnProduit = db.produits.some(p => p.nom.toLowerCase() === recherche);
  if (estUnProduit) return null;
  let client = db.clients.find(c =>
    c.nom.toLowerCase().includes(recherche) ||
    (c.telephone && String(c.telephone).includes(recherche)) ||
    (c.email && c.email.toLowerCase().includes(recherche))
  );
  if (!client) {
    client = {
      id: genId(), nom: info.trim(), email: "", telephone: "",
      note: "Créé via vente", nb_achats: 0, ca_total: 0,
      carte_envoyee: false, cree_le: new Date().toISOString(),
    };
    db.clients.push(client);
    envoyerVersSheets("nouveau_client", { nom: client.nom, email: "", telephone: "", note: client.note, date: new Date().toLocaleString("fr-FR", { timeZone: "Africa/Porto-Novo" }) });
  }
  return client;
}

// Enregistrer une vente avec gestion fidélité
// Vérifie si un produit est une paire de lunettes
function estDesLunettes(nomProduit) {
  // Tout produit qui n'est pas un étui/housse/accessoire = lunettes
  const motsExclus = ["etui", "étui", "housse", "case", "chiffon", "cordon", "spray", "produit"];
  return !motsExclus.some(m => nomProduit.toLowerCase().includes(m));
}

// Trouver l'étui dans le stock
function trouverEtui() {
  return db.produits.find(p =>
    p.nom.toLowerCase().includes("etui") ||
    p.nom.toLowerCase().includes("étui") ||
    p.nom.toLowerCase().includes("housse") ||
    p.nom.toLowerCase().includes("case")
  );
}

// Offrir l'étui automatiquement (déduire du stock sans facturer)
function offrirEtui(qte, clientNom) {
  const etui = trouverEtui();
  if (!etui) return null;
  if (etui.stock < qte) return { nom: etui.nom, erreur: "stock insuffisant", stock: etui.stock };

  const avant = etui.stock;
  etui.stock -= qte;

  db.historique_stock.unshift({
    id: genId(), produit_id: etui.id, produit_nom: etui.nom,
    operation: "remove", quantite: qte, stock_avant: avant, stock_apres: etui.stock,
    note: "Étui offert avec lunettes — " + clientNom,
    date: new Date().toISOString(),
  });

  envoyerVersSheets("mouvement_stock", {
    produit: etui.nom, operation: "remove", quantite: qte,
    stock_avant: avant, stock_apres: etui.stock,
    note: "Offert avec lunettes — " + clientNom,
    date: new Date().toLocaleString("fr-FR"),
  });

  return { nom: etui.nom, stock_restant: etui.stock, alerte: etui.stock <= 5 };
}

async function enregistrerVenteComplete(produitNomOuId, qte, clientInfo, prixVenteOverride = null, skipEmail = false) {
  // PRIORITÉ ABSOLUE : si un ID produit exact est fourni (objet déjà sélectionné par l'utilisateur
  // via les boutons de l'interface), on l'utilise directement — AUCUNE recherche, AUCUNE ambiguïté possible.
  let produit = db.produits.find(p => p.id === produitNomOuId);

  // Sinon, on retombe sur la recherche textuelle (cas de la vente texte / IA, où on n'a qu'un nom)
  const produitNom = produitNomOuId;
  if (!produit) {
    const normalize = s => String(s).toLowerCase().trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    produit = db.produits.find(p => {
      const nomAvecCouleur = p.couleur ? normalize(p.nom + " " + p.couleur) : normalize(p.nom);
      return nomAvecCouleur === normalize(produitNom);
    });
  }

  if (!produit) {
    // Pas de correspondance exacte → chercher les variantes du même modèle (sans deviner la couleur)
    const normalize2 = s => String(s).toLowerCase().trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const variantes = db.produits.filter(p => normalize2(p.nom) === normalize2(produitNom.split(' ')[0]));
    if (variantes.length === 1) {
      // Une seule couleur pour ce modèle → pas d'ambiguïté
      produit = variantes[0];
    } else if (variantes.length > 1) {
      // Plusieurs couleurs existent mais aucune ne correspond exactement → BLOQUER et demander
      const couleursListe = variantes.map(v => v.couleur).join(", ");
      return { erreur: `⚠️ Le modèle "${produitNom}" a plusieurs couleurs (${couleursListe}). Précisez la couleur exacte, par exemple : "${produitNom} ${variantes[0].couleur}".` };
    } else {
      // Aucun modèle exact trouvé → chercher par inclusion partielle du nom (sans couleur)
      const motsRecherche = produitNom.toLowerCase().split(' ');
      const nomSeul = motsRecherche[0]; // premier mot = nom du modèle probable
      const candidats = db.produits.filter(p => p.nom.toLowerCase().includes(nomSeul) || nomSeul.includes(p.nom.toLowerCase()));
      if (candidats.length === 0) {
        return { erreur: `Produit "${produitNom}" introuvable. Vérifiez le nom du modèle et la couleur.` };
      }
      const nomsUniques = [...new Set(candidats.map(c => c.nom))];
      if (nomsUniques.length > 1) {
        return { erreur: `⚠️ "${produitNom}" est ambigu, plusieurs modèles possibles : ${nomsUniques.join(", ")}. Précisez le nom exact.` };
      }
      const variantesCandidat = candidats.filter(c => c.nom === nomsUniques[0]);
      if (variantesCandidat.length === 1) {
        produit = variantesCandidat[0];
      } else {
        const couleursListe = variantesCandidat.map(v => v.couleur).join(", ");
        return { erreur: `⚠️ Le modèle "${nomsUniques[0]}" a plusieurs couleurs (${couleursListe}). Précisez la couleur exacte.` };
      }
    }
  }

  if (!produit) return { erreur: `Produit "${produitNom}" introuvable` };
  if (produit.stock < qte) return { erreur: `Stock insuffisant pour ${produit.nom}${produit.couleur?' — '+produit.couleur:''} (dispo: ${produit.stock})` };

  const client = clientInfo ? trouverOuCreerClient(clientInfo) : null;

  // Détecter si c'est une vente revendeur (prix override = prix revendeur du produit)
  const estVenteRevendeur = prixVenteOverride !== null && produit.prix_revendeur && prixVenteOverride === produit.prix_revendeur;

  // Appliquer réduction fidélité si éligible — JAMAIS sur une vente revendeur
  // (le prix revendeur est déjà un prix final négocié, pas de cumul de réduction)
  let prixVente = prixVenteOverride || produit.prix_vente;
  let reductionAppliquee = false;
  let montantAvant = 0;
  let montantReduction = 0;

  if (!estVenteRevendeur && client && clientEligibleReduction(client)) {
    montantAvant = parseFloat((prixVente * qte).toFixed(0));
    prixVente = appliquerReduction(prixVente, client.nb_achats);
    reductionAppliquee = true;
    montantReduction = montantAvant - parseFloat((prixVente * qte).toFixed(0));
  }

  const avant = produit.stock;
  produit.stock -= qte;

  // Mettre à jour le stock dans Google Sheets
  await envoyerVersSheets("mouvement_stock", {
    produit: produit.nom,
    couleur: produit.couleur || "",
    operation: "remove",
    quantite: qte,
    stock_avant: avant,
    stock_apres: produit.stock,
    note: `Vente`,
    date: new Date().toLocaleString("fr-FR", { timeZone: "Africa/Porto-Novo" })
  });

  const montant_total = parseFloat((prixVente * qte).toFixed(0));
  const marge_totale = parseFloat(((prixVente - produit.prix_achat) * qte).toFixed(0));

  const vente = {
    id: genId(),
    client_id: client ? client.id : null,
    client_nom: client ? client.nom : "Anonyme",
    produit_id: produit.id,
    produit_nom: produit.nom,
    produit_couleur: produit.couleur || "",
    produit_photo_url: produit.photo_url || null,
    prix_achat_unitaire: produit.prix_achat,
    prix_vente_unitaire: prixVente,
    prix_vente_normal: produit.prix_vente, // toujours le prix catalogue pour l'email
    is_revendeur: estVenteRevendeur,
    quantite: qte,
    montant_total,
    marge_totale,
    reduction_appliquee: reductionAppliquee,
    date: new Date().toISOString(),
  };

  db.ventes.unshift(vente);

  db.historique_stock.unshift({
    id: genId(), produit_id: produit.id, produit_nom: produit.nom,
    operation: "remove", quantite: qte, stock_avant: avant, stock_apres: produit.stock,
    note: `Vente — ${vente.client_nom}`, date: new Date().toISOString(),
  });

  // Mettre à jour compteur fidélité client — JAMAIS pour une vente revendeur
  if (client && !estVenteRevendeur) {
    client.nb_achats += 1;
    client.ca_total += montant_total;
    client.derniere_visite = new Date().toISOString();
    await envoyerVersSheets("mettre_a_jour_client", {
      id: client.id,
      nb_achats: client.nb_achats,
      ca_total: client.ca_total
    });

    // Email géré uniquement par envoyerEmailsApresVente dans finaliserVente
    // (supprimé ici pour éviter les doublons)
  } else if (client && estVenteRevendeur) {
    // Vente revendeur : on met juste à jour la dernière visite, jamais le compteur fidélité
    client.derniere_visite = new Date().toISOString();
  }

  envoyerVersSheets("nouvelle_vente", {
    client: vente.client_nom, produit: produit.nom, couleur: produit.couleur || "", quantite: qte,
    prix_vente: prixVente, montant_total, marge_totale,
    reduction: reductionAppliquee || 0,
    type_vente: vente.is_revendeur ? "Revendeur" : "Normal",
    date: new Date().toLocaleString("fr-FR"),
  });

  // Offrir étui automatiquement si c'est une vente de lunettes
  let etuiOffert = null;
  if (estDesLunettes(produit.nom)) {
    etuiOffert = offrirEtui(qte, client ? client.nom : "Anonyme");
  }

  const labelReduction = reductionAppliquee && client ? getLabelReduction(client.nb_achats - 1) : null;
  return { vente, produit, client, alerte: produit.stock <= 5, reductionAppliquee, montantReduction, montantAvant, etuiOffert, labelReduction };
}

// ─────────────────────────────────────────
// FINALISER UNE VENTE (partagé entre vente_client et nouveau_client)
// ─────────────────────────────────────────
async function finaliserVente(chatId, session, clientNom) {
  const panier = session.data.panier && session.data.panier.length > 0 ? session.data.panier : null;

  // ── PANIER MULTI-ARTICLES ──
  if (panier && panier.length > 1) {
    session.etape = null; session.data = {};
    let repGlobal = `✅ *Vente enregistrée !*\n👤 ${clientNom}\n\n`;
    let totalGlobal = 0;
    let firstResult = null;
    const ventesEnregistrees = [];

    for (const item of panier) {
      // On passe l'ID exact de l'objet produit déjà sélectionné — aucune reconstruction de texte, aucune ambiguïté
      const result = await enregistrerVenteComplete(item.produit.id, item.quantite, clientNom, item.prix_unitaire, true); // skipEmail=true pour panier
      if (!result.erreur) {
        totalGlobal += item.total;
        repGlobal += `🛒 *${item.produit.nom}${item.produit.couleur?' — '+item.produit.couleur:''}* x${item.quantite} = ${item.total} FCFA${item.reduction?' 🎁-'+item.reduction+'%':''}\n`;
        ventesEnregistrees.push(result);
        if (!firstResult) firstResult = result;
      } else { repGlobal += `❌ ${result.erreur}\n`; }
    }
    repGlobal += `\n💰 *Total: ${totalGlobal} FCFA*`;
    await sendMessage(chatId, repGlobal, { reply_markup: menuVentes() });

    // UN SEUL MAIL pour toute la vente multi-articles
    if (firstResult && firstResult.client && firstResult.client.email) {
      await envoyerEmailPanierComplet(firstResult.client, ventesEnregistrees, totalGlobal);
    } else if (firstResult && firstResult.client && !firstResult.client.email) {
      session.etape = "vente_client_email_apres";
      session.data = { result: firstResult, panier: ventesEnregistrees, totalGlobal };
    }
    return;
  }

  // ── ARTICLE UNIQUE ──
  if (panier && panier.length === 1) {
    session.data.produit = panier[0].produit;
    session.data.quantite = panier[0].quantite;
    session.data.prixOverride = panier[0].prix_unitaire;
  }

  let prixOverride = session.data.prixOverride || null;
  const supplement = session.data.supplement || null;
  const supplementParUnite = supplement ? Math.round(supplement.montant / (session.data.quantite || 1)) : 0;

  if (!prixOverride && session.data.reduction_manuelle && session.data.reduction_manuelle > 0) {
    const prixBase = session.data.produit.prix_vente * session.data.quantite;
    if (session.data.reduction_montant_exact) {
      prixOverride = Math.round((prixBase - session.data.reduction_montant_exact) / session.data.quantite);
    } else {
      prixOverride = Math.round(session.data.produit.prix_vente * (1 - session.data.reduction_manuelle / 100));
    }
  }
  // Ajouter le supplément au prix unitaire
  if (supplementParUnite > 0) {
    prixOverride = (prixOverride || session.data.produit.prix_vente) + supplementParUnite;
  }
  // On passe l'ID exact de l'objet produit déjà sélectionné — aucune reconstruction de texte, aucune ambiguïté
  const result = await enregistrerVenteComplete(session.data.produit.id, session.data.quantite, clientNom, prixOverride);
  if (result && result.vente && supplement) {
    result.vente.supplement = supplement;
  }
  if (result.erreur) {
    session.etape = "vente_texte"; session.data = {};
    return sendMessage(chatId, `❌ ${result.erreur}\n\n✏️ Réessayez en précisant bien le produit, la couleur, la quantité et le client :`, { reply_markup: { keyboard: [["❌ Annuler"]], resize_keyboard: true } });
  }

  // Si client sans email → demander l'email pour la carte fidélité
  if (result.client && !result.client.email) {
    session.etape = "vente_client_email_apres";
    session.data = { result };
    return sendMessage(chatId,
      `✅ *Vente enregistrée !*\n🛒 ${result.vente.produit_nom} x${result.vente.quantite}\n💰 *${result.vente.montant_total} FCFA*\n\n📧 Email de *${result.client.nom}* pour sa carte fidélité :`,
      { reply_markup: { keyboard: [["❌ Pas d'email"], ["❌ Annuler"]], resize_keyboard: true } }
    );
  }

  session.etape = null; session.data = {};

  // Envoi email centralisé
  await envoyerEmailsApresVente(result);

  // Notification stock critique (<=2)
  if (result.produit.stock <= 2 && result.produit.stock > 0) {
    await sendMessage(chatId, `🚨 *STOCK CRITIQUE !*\n📦 ${result.produit.nom}${result.produit.couleur?' — '+result.produit.couleur:''}\n⚠️ Il ne reste que *${result.produit.stock}* unité(s) !`);
  } else if (result.produit.stock === 0) {
    await sendMessage(chatId, `🔴 *RUPTURE DE STOCK !*\n📦 ${result.produit.nom}${result.produit.couleur?' — '+result.produit.couleur:''}\n❌ Plus aucune unité disponible !`);
  }

  let rep = `✅ *Vente enregistrée !*\n🛒 ${result.vente.produit_nom} x${result.vente.quantite}\n👤 ${result.vente.client_nom}\n💰 *${result.vente.montant_total} FCFA*${result.vente.supplement?`\n🔵 ${result.vente.supplement.nom}: +${result.vente.supplement.montant} FCFA`:''}\n📈 Marge: ${result.vente.marge_totale} FCFA\n📦 Restant: ${result.produit.stock}`;
  if (result.reductionAppliquee) rep += `\n\n🎁 *Réduction fidélité ${result.labelReduction || ''} appliquée !*\n💸 Économie : ${result.montantReduction} FCFA`;
  if (result.etuiOffert) {
    if (result.etuiOffert.erreur) {
      rep += `\n\n⚠️ *Étui non inclus* — stock insuffisant (${result.etuiOffert.stock} dispo)`;
    } else {
      rep += `\n\n🕶️ *Étui offert !* — ${result.etuiOffert.nom} déduit du stock`;
      if (result.etuiOffert.alerte) rep += `\n⚠️ Stock étuis bas (${result.etuiOffert.stock_restant} restant(s))`;
    }
  }
  if (result.alerte) rep += `\n\n⚠️ *Stock bas !* ${result.produit.nom}${result.produit.couleur?' — '+result.produit.couleur:''} → ${result.produit.stock} restant(s)`;
  return sendMessage(chatId, rep, { reply_markup: menuVentes() });
}

function formatDateFR(dateISO) {
  const d = new Date(dateISO);
  const opts = { weekday:'long', day:'numeric', month:'long', year:'numeric', hour:'2-digit', minute:'2-digit', hour12: false };
  // Formatter en français avec heure Bénin
  const str = d.toLocaleString('fr-FR', opts);
  // str = "mercredi 27 mai à 15:00" → capitaliser
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function calculerRappels(dateEvent) {
  const d = new Date(dateEvent);
  const matin = new Date(d);
  matin.setHours(8, 0, 0, 0);
  if (matin >= d) matin.setDate(matin.getDate() - 1);
  return [
    { type: "1j",    time: new Date(d.getTime() - 24 * 60 * 60 * 1000), label: "⏰ Rappel J-1 — demain !" },
    { type: "matin", time: matin,                                         label: "🌅 Rappel matin" },
    { type: "1h",    time: new Date(d.getTime() - 60 * 60 * 1000),       label: "⏱️ Rappel dans 1h" },
    { type: "30min", time: new Date(d.getTime() - 30 * 60 * 1000),       label: "🔔 Dans 30 min !" },
    { type: "heure", time: new Date(d.getTime()),                         label: "🚨 C'est maintenant !" },
  ];
}

function demarrerRappels() {
  // Vérification rappels toutes les 30 secondes
  setInterval(async () => {
    const maintenant = new Date();
    for (const event of db.agenda) {
      if (new Date(event.date) < maintenant) continue;
      const rappels = calculerRappels(event.date);
      for (const rappel of rappels) {
        if (event.rappels_envoyes.includes(rappel.type)) continue;
        const diff = rappel.time.getTime() - maintenant.getTime();
        // Fenêtre élargie à 90 secondes pour ne rien rater
        if (diff >= -90000 && diff <= 90000) {
          console.log(`🔔 Envoi rappel "${rappel.label}" pour "${event.titre}"`);
          await sendMessage(event.chatId, `${rappel.label}\n\n📅 *${event.titre}*\n🕐 ${formatDateFR(event.date)}`);
          event.rappels_envoyes.push(rappel.type);
        }
      }
    }
    // Nettoyer les événements passés depuis plus de 24h
    db.agenda = db.agenda.filter(e => new Date(e.date).getTime() > Date.now() - 24 * 60 * 60 * 1000);

    // Rappels relances
    for (const relance of db.relances) {
      if (relance.statut === "✅ Fait" || new Date(relance.date) < maintenant) continue;
      const rappels = calculerRappels(relance.date);
      for (const rappel of rappels) {
        if (relance.rappels_envoyes.includes(rappel.type)) continue;
        const diff = rappel.time.getTime() - maintenant.getTime();
        if (diff >= -90000 && diff <= 90000) {
          await sendMessage(relance.chatId, `${rappel.label} — Relance client\n\n📞 *${relance.client_nom}*${relance.client_tel ? "\n📱 " + relance.client_tel : ""}${relance.note ? "\n📝 " + relance.note : ""}\n🕐 ${formatDateFR(relance.date)}`);
          relance.rappels_envoyes.push(rappel.type);
        }
      }
    }

    // Rappels livraisons
    for (const livraison of db.livraisons) {
      if (livraison.statut === "✅ Livré" || new Date(livraison.date) < maintenant) continue;
      const rappels = calculerRappels(livraison.date);
      for (const rappel of rappels) {
        if (livraison.rappels_envoyes.includes(rappel.type)) continue;
        const diff = rappel.time.getTime() - maintenant.getTime();
        if (diff >= -90000 && diff <= 90000) {
          await sendMessage(livraison.chatId, `${rappel.label} — Livraison\n\n🚚 *${livraison.client_nom}*${livraison.client_tel ? "\n📱 " + livraison.client_tel : ""}${livraison.produit ? "\n🛒 " + livraison.produit : ""}${livraison.note ? "\n📝 " + livraison.note : ""}\n🕐 ${formatDateFR(livraison.date)}`);
          livraison.rappels_envoyes.push(rappel.type);
        }
      }
    }
  }, 30000);

  // Auto-ping toutes les 10 minutes pour garder Render éveillé
  setInterval(async () => {
    try {
      await axios.get(RENDER_URL + "/ping");
      console.log("🏓 Ping Render OK");
    } catch (err) {
      console.log("🏓 Ping Render :", err.message);
    }
  }, 10 * 60 * 1000);

  console.log("🔔 Rappels démarrés (intervalle 30s) + auto-ping 10min");
}

